 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    if len(points) != 2:
        raise ValueError("expected two 5 markers")

    def component(start):
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr,nc) not in seen:
                    seen.add((nr,nc))
                    q.append((nr,nc))
        return seen

    comps = [component(p) for p in points]
    embedded = [i for i, comp in enumerate(comps) if len(comp) > 1]
    if len(embedded) != 1:
        raise ValueError("could not identify source marker")
    src_i = embedded[0]
    src, dst = points[src_i], points[1-src_i]
    obj = comps[src_i]
    dr, dc = dst[0] - src[0], dst[1] - src[1]

    out = [row[:] for row in grid]
    out[dst[0]][dst[1]] = 0
    for r, c in obj:
        if (r, c) == src:
            continue
        nr, nc = r + dr, c + dc
        if not (0 <= nr < h and 0 <= nc < w):
            raise ValueError("translated object is out of bounds")
        out[nr][nc] = grid[r][c]
    return out
